//---------------------------------------------------------------------------//
// Unit test for tools/rcmp
// Initial implementation generated by GitHub CoPilot (GPT-4.1)
//---------------------------------------------------------------------------//
#include "tools/rcmp"

#include <gtest/gtest.h>

namespace tools
{
//---------------------------------------------------------------------------//
TEST(Rcmp, EqualStrings)
{
  EXPECT_TRUE(rcmp("abc", "abc"));
  EXPECT_TRUE(rcmp(std::string("abc"), "abc"));
  EXPECT_TRUE(rcmp("abc", std::string("abc")));
  EXPECT_TRUE(rcmp(std::string("abc"), std::string("abc")));
}

TEST(Rcmp, ReverseEqualStrings)
{
  EXPECT_FALSE(rcmp("abc", "cba"));
  EXPECT_FALSE(rcmp(std::string("abc"), "cba"));
  EXPECT_FALSE(rcmp("abc", std::string("cba")));
  EXPECT_FALSE(rcmp(std::string("abc"), std::string("cba")));
}

TEST(Rcmp, NotEqualStrings)
{
  EXPECT_FALSE(rcmp("abc", "def"));
  EXPECT_FALSE(rcmp(std::string("abc"), "def"));
  EXPECT_FALSE(rcmp("abc", std::string("def")));
  EXPECT_FALSE(rcmp(std::string("abc"), std::string("def")));
}

TEST(Rcmp, DifferentLengths)
{
  EXPECT_FALSE(rcmp("abc", "bc"));
  EXPECT_FALSE(rcmp(std::string("abc"), "bc"));
  EXPECT_FALSE(rcmp("abc", std::string("bc")));
  EXPECT_FALSE(rcmp(std::string("abc"), std::string("bc")));
}

TEST(Rcmp, EmptyStrings)
{
  EXPECT_TRUE(rcmp("", ""));
  EXPECT_TRUE(rcmp(std::string(""), ""));
  EXPECT_TRUE(rcmp("", std::string("")));
  EXPECT_TRUE(rcmp(std::string(""), std::string("")));
}

TEST(Rcmp, SingleCharacter)
{
  EXPECT_TRUE(rcmp("a", "a"));
  EXPECT_FALSE(rcmp("a", "b"));
}

TEST(Rcmp, Palindrome)
{
  EXPECT_TRUE(rcmp("aba", "aba"));  // same forwards and backwards
  EXPECT_FALSE(rcmp("aba", "bab"));
}

TEST(Rcmp, CaseSensitivity)
{
  EXPECT_FALSE(rcmp("abc", "ABC"));
  EXPECT_FALSE(rcmp(std::string("abc"), "ABC"));
}

TEST(Rcmp, NumericStrings)
{
  EXPECT_TRUE(rcmp("123", "123"));
  EXPECT_FALSE(rcmp("123", "321"));
  EXPECT_TRUE(rcmp("a1b2c3", "a1b2c3"));
}

TEST(Rcmp, NamespaceQualifiedTypes)
{
  EXPECT_TRUE(rcmp("std::string", "std::string"));
  EXPECT_FALSE(rcmp("std::string", "string"));
  EXPECT_TRUE(rcmp("tools::vec3f", "tools::vec3f"));
  EXPECT_FALSE(rcmp("tools::vec3f", "vec3f"));
}

TEST(Rcmp, TemplateTypes)
{
  EXPECT_TRUE(rcmp("std::vector<int>", "std::vector<int>"));
  EXPECT_FALSE(rcmp("std::vector<int>", "std::vector<float>"));
  EXPECT_TRUE(rcmp("std::map<int,std::string>", "std::map<int,std::string>"));
}

//---------------------------------------------------------------------------//
}  // namespace tools
